import{z as s,x as B,o as r,c as A,q as o,j as l,D as e,d as n,s as i,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"上境图与下水平集","description":"","frontmatter":{"title":"上境图与下水平集","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/epigraph-sublevel.md","filePath":"econ/epigraph-sublevel.md","lastUpdated":1791413859000}'),f={name:"econ/epigraph-sublevel.md"};function d(h,a,m,x,g,c){const t=B("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="上境图与下水平集" tabindex="-1">上境图与下水平集 <a class="header-anchor" href="#上境图与下水平集" aria-label="Permalink to &quot;上境图与下水平集&quot;">​</a></h1><div class="epigraph"><p>函数凸当且仅当上境图凸：把弯曲的函数值问题，送回上一课已经会的点集几何。</p><footer>—— 据 Boyd and Vandenberghe, Convex Optimization, 第 3 章；Rockafellar, Convex Analysis, 1970 整理</footer></div><p>上一课<a href="/econ/convex-concave-fn">凸函数与凹函数</a>用弦定义了凸。计算上有时更顺手的是集合：把函数抬到一维，看「图的上方」是不是凸集。缺口不是再写一遍弦不等式，而是上境图与下水平集这两套语言，以及它们怎样把后课的分离定理接到函数上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>函数 \\(f:C\\to\\mathbb{R}\\) 的<strong>上境图</strong>（epigraph）是 \\(\\operatorname{epi} f=\\{(x,t)\\in C\\times\\mathbb{R}: t\\ge f(x)\\}\\)。 图在下面，竖直方向往上的半边都算进去。\\(f\\) 凸当且仅当 \\(\\operatorname{epi} f\\) 作为 \\(\\mathbb{R}^{n+1}\\) 的子集是凸集。凹函数看<strong>下境图</strong> \\(\\{t\\le f(x)\\}\\)，或直接对 \\(-f\\) 取上境图。</p><p><strong>下水平集</strong> \\(S_\\alpha=\\{x:f(x)\\le\\alpha\\}\\)。凸函数的每个下水平集都凸；反过来不真——拟凸函数也有凸下水平集，但不必凸。拟凸比凸弱，正好对应「水平集形状对、函数值弯曲不对」。最大化问题里对称的对象是上水平集 \\(\\{f\\ge\\alpha\\}\\)：凹与拟凹。</p><p><span class="marginnote">直觉类比：上境图就是「把函数图像上方整块涂黑得到的区域」。\\(f(x)=x^2\\) 的上境图是抛物线上方那碗不凹陷的「碗底以上」；函数凸，说的正是这块区域没有凹陷。而水平集是「碗上某条刻度线以下的部分」——把维数压回去一层。</span></p><p><span class="marginnote">常见误区：初学者容易以为「下水平集都凸就能当凸函数用」。反例：\\(f(x)=\\sqrt{|x|}\\) 的每个下水平集都是凸区间，但弦会掉到函数下方——它只是拟凸。拟凸保证「局部最优即全局最优」这种事并不成立到一阶条件充分的地步。</span></p><h3 id="上境图不是无差异曲线" tabindex="-1">上境图不是无差异曲线 <a class="header-anchor" href="#上境图不是无差异曲线" aria-label="Permalink to &quot;上境图不是无差异曲线&quot;">​</a></h3><p>无差异曲线是效用的水平集，画在商品空间里。上境图多一维，多出来的坐标是函数值本身。把两者画在同一张两商品图上会混：无差异曲线谈的是偏好序，上境图谈的是某一个实值函数的几何。后课效用还没有出场；本课的 \\(f\\) 可以是成本、利润、支出，不必是 \\(u\\)。</p><p><span class="marginnote">闭上境图 \\(\\Leftrightarrow\\) \\(f\\) 下半连续。Weierstrass 的下半连续版：下半连续函数在紧集上达到最小。最小化成本时，这个方向才是对的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>点态上确界：\\(f(x)=\\sup_{s\\in S} f_s(x)\\)。每个 \\(f_s\\) 凸则 \\(f\\) 凸，因为上境图是各 \\(\\operatorname{epi} f_s\\) 的交，凸集对交封闭。利润函数 \\(\\pi(p)=\\sup_x\\{p\\cdot y(x)-c(x)\\}\\) 是一族仿射函数的上包络，故对价格凸——这是后课<a href="/econ/shephard-hotelling">谢泼德引理与霍特林引理</a>的几何前半段。本课不写包络定理，只指出上境图对交封闭给出「包络仍凸」。</p><p>下水平集给出约束集合。\\(\\{x:g(x)\\le 0\\}\\) 在 \\(g\\) 凸时是凸集。KKT 里不等式约束常假设 \\(g_j\\) 凸，可行域才凸，一阶条件才充分。等式约束 \\(h(x)=0\\) 两边都不是水平集的凸形状能保证的：只有仿射 \\(h\\) 保住凸可行域。这是后课<a href="/econ/lagrange-multiplier">拉格朗日乘子</a>把等式限制在线性预算上的几何理由。</p>',14)),(r(),l(p,null,{default:e(()=>[i(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%AE%9E%E5%80%BC%E5%87%BD%E6%95%B0%20f%22%5D%20--%3E%20E%5B%22%E4%B8%8A%E5%A2%83%E5%9B%BE%20epi%20f%22%5D%0A%20%20F%20--%3E%20L%5B%22%E4%B8%8B%E6%B0%B4%E5%B9%B3%E9%9B%86%20S_alpha%22%5D%0A%20%20E%20--%3E%20CX%5B%22epi%20%E5%87%B8%20%E5%BD%93%E4%B8%94%E4%BB%85%E5%BD%93%20f%20%E5%87%B8%22%5D%0A%20%20L%20--%3E%20Q%5B%22%E4%B8%8B%E6%B0%B4%E5%B9%B3%E9%9B%86%E5%87%B8%EF%BC%9A%E6%8B%9F%E5%87%B8%22%5D%0A%20%20CX%20--%3E%20SEP%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AF%B9%20epi%20%E5%81%9A%E5%88%86%E7%A6%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"分离超平面作用在点集上。要把「点 \\(x_0\\) 不在凸函数 \\(f\\) 的图的下方」写成价格，最干净的办法是在 \\(\\operatorname{epi} f\\) 里分离 \\((x_0,f(x_0))\\) 的下方点。得到的法向量拆成对 \\(x\\) 的部分和对 \\(t\\) 的部分：前者是次梯度，后者归一化成 \\(1\\)。次梯度不等式 \\(f(y)\\ge f(x)+g^\\top(y-x)\\) 就是这条分离的坐标写法。下一课把分离本身讲清楚；本课只准备被分离的那个集合。",-1)),a[5]||(a[5]=E("p",null,"水平集管可行性，上境图管目标值。一个凸规划可以同时读成：在凸下水平集（约束）上，求上境图最靠下的点（目标）。两套集合都凸时，支撑超平面存在，影子价格才有几何。",-1)),(r(),l(p,null,{default:e(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%AF%95%E6%8E%A2%E7%82%B9%E8%90%BD%E5%9C%A8%E5%9B%BE%E4%B8%8B%E6%96%B9%22%5D%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%E8%B6%85%E5%B9%B3%E9%9D%A2%E9%9A%94%E5%BC%80%E5%AE%83%E4%B8%8E%20epi%20f%22%5D%0A%20%20SEP%20--%3E%20NV%5B%22%E5%88%86%E7%A6%BB%E9%9D%A2%E7%9A%84%E6%B3%95%E5%90%91%E9%87%8F%E6%8B%86%E6%88%90%E4%B8%A4%E6%88%AA%22%5D%0A%20%20NV%20--%3E%20GX%5B%22%E5%AF%B9%20x%20%E7%9A%84%E5%88%86%E9%87%8F%3A%20%E6%AC%A1%E6%A2%AF%E5%BA%A6%20g%22%5D%0A%20%20NV%20--%3E%20GT%5B%22%E5%AF%B9%20t%20%E7%9A%84%E5%88%86%E9%87%8F%E5%BD%92%E4%B8%80%E5%8C%96%E6%88%90%201%22%5D%0A%20%20GX%20--%3E%20INEQ%5B%22%E5%9D%90%E6%A0%87%E5%86%99%E6%B3%95%20%3D%20%E6%AC%A1%E6%A2%AF%E5%BA%A6%E4%B8%8D%E7%AD%89%E5%BC%8F%22%5D%0A%20%20GT%20--%3E%20INEQ%0A%20%20INEQ%20--%3E%20PRICE%5B%22%E6%94%AF%E6%92%91%E4%BB%B7%E6%A0%BC%20%2F%20%E5%BD%B1%E5%AD%90%E4%BB%B7%E6%A0%BC%E7%9A%84%E5%87%A0%E4%BD%95%E6%9D%A5%E6%BA%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：\\(f(x)=|x|\\) 在 \\(x=0\\) 不可导，但次梯度是整条区间 \\([-1,1]\\)——任取 \\(g=0.5\\)，次梯度不等式说 \\(|y|\\ge 0+0.5\\,y\\)：取 \\(y=-1\\) 得 \\(1\\ge -0.5\\)，成立。不可导点没有唯一切线，却有一整束合格的「支撑线」，这就是集值次梯度。</span></p><p><span class="marginnote">拟凸最小化仍可能有「看起来像切点、其实不是全局」的麻烦，因为拟凸不管函数值的弦。充分性要凸目标，不只是凸水平集。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Fenchel 共轭写成教材：共轭的上境图是支撑函数的几何，后课对偶会用到支出函数，但不在这里展开 Young 不等式。也不把水平集读成无差异曲线族——那要等到<a href="/econ/continuity-preference">连续性</a>之后。下一课对不相交凸集动手，给出支撑价格。</p><p>后课默认：说函数凸，可改口说上境图凸；说约束 \\(g\\le 0\\) 给出凸可行域，默认 \\(g\\) 凸。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上境图凸 \\(\\Leftrightarrow\\) 函数凸；这是把函数送回点集几何的桥梁。</li><li>下水平集凸是拟凸，弱于凸；最大化对应上水平集与拟凹。</li><li>点态上确界保凸，解释利润、支出作为包络的凸性。</li><li>不等式凸约束给出凸可行域；非线性等式会毁掉凸。</li><li>下一课：<a href="/econ/separating-hyperplane">分离超平面</a>。</li><li>出处：Boyd and Vandenberghe, <em>Convex Optimization</em>；Rockafellar, <em>Convex Analysis</em>。</li></ul>',7))])}const D=s(f,[["render",d]]);export{_ as __pageData,D as default};
